// ❌ 문제: 필터 변경 시 이전 LastEvaluatedKey 그대로 사용
const lastEvaluatedKey = event.queryStringParameters?.lastEvaluatedKey 
  ? JSON.parse(event.queryStringParameters.lastEvaluatedKey) 
  : undefined;

// ✅ 해결: 필터 변경 감지 시 LastEvaluatedKey 초기화
const currentFilter = event.queryStringParameters?.category || 'all';
const previousFilter = event.queryStringParameters?.previousCategory;

let lastEvaluatedKey = undefined;
if (event.queryStringParameters?.lastEvaluatedKey) {
  // 필터가 변경되었으면 페이지네이션 초기화
  if (previousFilter && previousFilter !== currentFilter) {
    lastEvaluatedKey = undefined; // 초기화
  } else {
    lastEvaluatedKey = JSON.parse(event.queryStringParameters.lastEvaluatedKey);
  }
}

// 쿼리 구성 시 필터에 따라 다른 키 스키마 사용
const params: QueryCommandInput | ScanCommandInput = 
  currentFilter === 'all' 
    ? {
        TableName: PARTS_TABLE_NAME,
        Limit: pageSize,
        ExclusiveStartKey: lastEvaluatedKey, // 테이블 키만 포함
        // ... 스캔 파라미터
      }
    : {
        TableName: PARTS_TABLE_NAME,
        IndexName: 'GSI2', // 카테고리 인덱스
        KeyConditionExpression: 'category = :cat',
        ExpressionAttributeValues: { ':cat': currentFilter },
        ExclusiveStartKey: lastEvaluatedKey, // GSI2 키 포함
        // ... 쿼리 파라미터
      };
```

