// 재시도 로직 개선 (현재 4회 → 최소 8회)
// 재시도 간격: 2^attempt * 100ms (최대 5초)

const batchGetWithRetry = async (keys, maxRetries = 8) => {
  let unprocessedKeys = keys;
  let attempt = 0;

  while (unprocessedKeys.length > 0 && attempt < maxRetries) {
    try {
      const response = await dynamodb.batchGetItem({
        RequestItems: {
          'BatteryTable': {
            Keys: unprocessedKeys.slice(0, 25), // 25개씩 분할
            ConsistentRead: false
          }
        }
      }).promise();

      unprocessedKeys = response.UnprocessedKeys?.BatteryTable?.Keys || [];
      attempt++;

      if (unprocessedKeys.length > 0) {
        const waitTime = Math.min(1000 * Math.pow(2, attempt), 5000);
        await new Promise(resolve => setTimeout(resolve, waitTime));
      }
    } catch (error) {
      throw error;
    }
  }
};
```

